68	    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
69	        string email,
70	        Guid issuedByUserId,
71	        SystemRole callerRole,
72	        string frontendBaseUrl,
73	        Guid? boardId = null,
74	        BoardRole? boardRole = null,
75	        CancellationToken cancellationToken = default)
76	    {
77	        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("email") }.ValidateAndThrow(email);
78	        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("issuedByUserId") }.ValidateAndThrow(issuedByUserId);
79	        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("frontendBaseUrl") }.ValidateAndThrow(frontendBaseUrl);
80	
81	        // System invitations require admin. Board invitations are pre-authorised by the caller
82	        // (BoardMembershipService checks board role before calling here).
83	        if (boardId is null && callerRole != SystemRole.Admin)
84	            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");
85	
86	        return await RetryPolicy.ExecuteAsync(async ct =>
87	        {
88	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
89	            try
90	            {
91	                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
92	                if (existing is not null)
93	                {
94	                    var refreshToken = InvitationToken.Generate();
95	                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
96	                    await _invitationRepository.RefreshTokenAsync(
97	                        existing.Id, refreshToken.Hash, newExpiry, tx);
98	                    tx.Commit();
99	                    _logger.LogInformation(
100	                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
101	                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
102	                }
103	
104	                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
105	                if (registeredUser is not null)
106	                    throw new ConflictException(
107	                        "invite.already_registered", "This email address is already registered.");
108	
109	                var token = InvitationToken.Generate();
110	                var issuedAt = DateTimeOffset.UtcNow;
111	                var invitation = new Invitation(
112	                    id: Guid.NewGuid(),
113	                    email: email,
114	                    issuedByUserId: issuedByUserId,
115	                    tokenHash: token.Hash,
116	                    issuedAt: issuedAt,
117	                    expiresAt: issuedAt.AddDays(7),
118	                    consumedAt: null,
119	                    consumedByUserId: null,
120	                    boardId: boardId,
121	                    boardRole: boardRole);
122	
123	                await _invitationRepository.InsertAsync(invitation, tx);
124	
125	                var authEvent = new AuthEvent(
126	                    Id: Guid.NewGuid(),
127	                    OccurredAt: issuedAt,
128	                    EventType: AuthEventType.InvitationIssued,
129	                    UserId: issuedByUserId,
130	                    Outcome: "success");
131	                await _authEventRepository.RecordAsync(authEvent, tx);
132	
133	                tx.Commit();
134	
135	                _logger.LogInformation(
136	                    "Invitation issued by {IssuedByUserId}", issuedByUserId);
137	
138	                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
139	            }
140	            catch
141	            {
142	                tx.Rollback();
143	                throw;
144	            }
145	        }, cancellationToken);
146	    }
