31	    [Fact]
32	    public async Task HandleSignInAsync_AdminFirstSignIn_LinksGoogleSubAndAddsClaims()
33	    {
34	        var admin = UserBuilder.AUser().AsAdmin().WithoutGoogleSub().WithEmail("admin@example.com").Build();
35	        var userRepo = new FakeUserRepository(byGoogleSub: null, byEmail: admin);
36	        var authEventRepo = new FakeAuthEventRepository();
37	        var sut = CreateSut(userRepo, authEventRepo);
38	        var identity = new ClaimsIdentity();
